  function candidateSummary(){const p=progressProfiles[state.progressCandidate]||progressProfiles.a01;return shell(`<div class="system-inner">${crumb('申请人履历摘要')}<h2 class="page-title">申请人履历摘要</h2><p class="small muted">用于方向接收进度展示；不构成正式录取或学籍信息。</p><div class="profile-sheet"><dl><dt>展示姓名</dt><dd>${escape(p.name)}</dd><dt>本科院校</dt><dd>${escape(p.school)}</dd><dt>申请方向</dt><dd>${escape(p.major)}</dd><dt>项目经历</dt><dd>${escape(p.project)}</dd><dt>材料状态</dt><dd>已纳入本方向进度展示</dd></dl><div class="profile-note"><b>资料说明</b><p>页面字段依据本轮提交材料生成。若展示内容与本人提交材料不一致，请以正式审核通知为准。</p></div></div><div class="form-actions"><button class="secondary" data-action="route" data-route="rank">返回方向接收进度</button></div></div>`);}
  function rank(){if(!state.submitted)return status();const rows=[['1','a01','拟接收展示','2026-09-22 09:12'],['2','lzy','拟接收展示','2026-09-22 09:15'],['3','a03','拟接收展示','2026-09-22 09:12'],['4','a04','拟接收展示','2026-09-22 09:14'],['5','a05','拟接收展示','2026-09-22 09:11'],['6','a06','拟接收展示','2026-09-22 09:13'],['7','chen','候补 · 顺位 1','2026-09-22 09:20'],['8','zhao','候补 · 顺位 2','2026-09-22 09:20'],['9','b03','候补 · 顺位 3','2026-09-22 09:20'],['10','b04','候补 · 顺位 4','2026-09-22 09:20']];return shell(`<div class="system-inner">${crumb('方向接收进度')}<div class="rank-summary"><div><span class="label">候补顺位</span><span class="rank-number">${state.rosterInquiry.result?'已递补':'01'}</span></div><div><h2>${state.rosterInquiry.result?'陈言，你已取得递补拟录取资格。':'陈言，你当前位于候补组第 1 位。'}</h2><p>方向接收进度会随审核安排更新。<br>更新时间：${state.rosterInquiry.result?'2026年9月24日 09:12':'2026年9月22日 09:20'}</p></div></div><p class="small muted">本页为方向接收进度，最终结果以正式审核通知为准。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>序号</th><th>姓名</th><th>申请方向</th><th>展示状态</th><th>最近更新</th></tr></thead><tbody>${rows.map(r=>{const p=progressProfiles[r[1]];return `<tr ${r[0]==='7'?'class="me"':''}><td>${r[0]}</td><td><button class="table-link" data-action="candidate-summary" data-candidate="${r[1]}">${escape(p.name)}</button></td><td>${escape(p.major)}</td><td>${state.rosterInquiry.result&&r[1]==='lzy'?'已更正，不再计列':state.rosterInquiry.result&&r[1]==='chen'?'递补拟录取 · '+offerStatus():r[2]}</td><td>${state.rosterInquiry.result&&['lzy','chen'].includes(r[1])?'2026-09-24 09:12':r[3]}</td></tr>`;}).join('')}</tbody></table></div><p class="small muted" style="line-height:1.9">${state.rosterInquiry.result?'HC-014经核查不再计列，释放1个递补名额；其余条目沿用本轮既有记录。':'前六行是本方向当前展示的拟接收名单；候补组的顺位仅在候补申请人之间计算。'}</p><div class="form-actions"><button class="secondary" data-action="save-rank">保存当前表格副本</button><button class="primary" data-action="route" data-route="forum">查看申请交流区</button></div></div>`);}
  function followup(){return shell(`<div class="system-inner">${crumb('夏令营材料留存')}<h2 class="page-title">七月夏令营材料留存</h2><p class="small muted">本页仅汇总本人留存的营期通知、行程和活动确认文件。</p><div class="task-card"><h3>已登记文件</h3><p>报到与研究院参观、导师交流、项目介绍、招生咨询与活动总结。</p><p>如需核对，请以本人保存的通知、车票和活动确认回执为准。该页面不构成新增考核，也不包含入学后的培养记录。</p><button class="secondary" data-action="files-folder" data-folder="july">打开七月文件</button></div></div>`);}
  function forum(){return `<section class="community-page"><div class="community-head"><span>衡川大学先进系统研究院</span><h1>申请人交流区</h1><p>仅用于流程性问题交流。请勿公开本人完整材料、证件或他人私人通讯。</p></div><div class="community-list"><article class="community-post"><div class="post-meta">赵可宁 · 候补申请人　2026-09-22 09:31</div><h2>同一封补材料通知会有两个版本吗？</h2><p>我的邮件写的是“补交项目说明”，朋友收到的邮件又提到“确认个人陈述版本”。日期和发件地址一样，我不想把整封邮件贴出来。</p><div class="post-reply"><b>陈言</b>　${state.zhaoAdded?'已添加联系方式；请到聊天中由本人主动发起核对。':'我这边也是先核对个人陈述和项目说明。'}<button class="text" data-action="add-zhao" ${state.zhaoAdded?'disabled':''}>${state.zhaoAdded?'已添加联系方式':'添加联系方式，仅核对通知'}</button></div></article><article class="community-post"><div class="post-meta">蒋思齐 · 拟接收展示　2026-09-22 09:29</div><h2>补交文件的命名需要和七月版本一致吗？</h2><p>我保留了夏令营时的文件名，今天只补了一份项目说明。系统回执里能看到附件名，建议先把回执保存下来。</p><button class="text" data-action="files-folder" data-folder="application">查看本人申请材料</button></article><article class="community-post"><div class="post-meta">系统公告　2026-09-22 09:25</div><h2>方向接收进度说明</h2><p>展示名单、候补申请人与正式接收结果属于不同状态。请以本人邮件和后续审核通知为准。</p><button class="secondary" data-action="route" data-route="rank">查看方向接收进度</button></article><article class="community-post"><div class="post-meta">林知远　2026-09-22 09:28</div><h2>项目说明里要写到什么程度？</h2><p>课程项目是小组完成的，我只写自己做过的数据整理和模型验证，应该够了吗？</p><button class="text" data-action="route" data-route="lzyThread">查看讨论串</button></article><article class="community-post"><div class="post-meta">许澄 · 夏令营申请人　2026-09-22 09:27</div><h2>七月的活动回执只写了到场，还需要补别的吗？</h2><p>我理解回执只是活动留存。现在还是按今天这封邮件的材料要求走，别把行程单当作新的审核材料。</p></article><article class="community-post"><div class="post-meta">匿名申请人　2026-09-22 09:26</div><h2>问卷结果是马上出吗？</h2><p>我把和竞争有关的选项都选得很高，结果还是显示常规复核。是不是还会看对统一反馈的接受程度？</p><button class="secondary" data-action="route" data-route="questionnaire">进入本人问卷</button></article></div></section>`;}
  function campusHeader(compact=false){const c=campus(),q=state.campusQuery||'';return `<header class="campus-head ${compact?'compact':''}" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}"><div class="campus-mark" aria-hidden="true"><span>${c.name.slice(0,1)}</span></div><div class="campus-title"><span>${c.english}</span><h1>${c.name}</h1></div><form data-campus-form><input aria-label="${c.name}站内搜索" data-campus-search value="${escape(q)}" placeholder="搜索新闻、通知、院系、人员"><button class="primary">搜索</button></form></header>`;}
  function campusHome(){const c=campus();return `<section class="campus-page" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}">${campusHeader()}<nav class="campus-nav"><span>学校概况</span><span>人才培养</span><span>科学研究</span><span>校园生活</span><span>信息公开</span><span>办事服务</span></nav><main class="campus-layout"><section class="campus-feature"><div class="campus-feature-art" aria-hidden="true"><i></i><b></b><em></em></div><div class="campus-feature-copy"><p class="campus-kicker">校园要闻 · 2026.09</p><h2>${c.lead}</h2><p>${c.leadText}</p><button class="text" data-action="campus-search" data-query="${c.lead.slice(0,8)}">查看相关报道</button></div></section><aside class="campus-notices"><div class="campus-section-title"><h2>通知公告</h2><span>更多</span></div>${c.notices.map((item,i)=>`<button class="campus-list-link" data-action="campus-article" data-article="${state.campusKey}-notice-${i}"><span>${item}</span><time>09-${18-i*2}</time></button>`).join('')}</aside><section class="campus-services"><div class="campus-section-title"><h2>常用服务</h2><span>服务大厅</span></div><div class="service-grid">${c.services.map((name,i)=>`<button class="service-tile" data-action="campus-service" data-service="${i}"><b>${name}</b><span>${i===1&&c===campuses.ningchuan?'历史资料与项目归档':c.serviceIntro}</span></button>`).join('')}</div></section><section class="campus-digest"><div class="campus-section-title"><h2>院系动态</h2><span>全部动态</span></div>${c.schools.map((item,i)=>`<button class="campus-digest-link" data-action="campus-article" data-article="${state.campusKey}-digest-${i}"><time>2026.09.${15-i*2}</time><span><b>${item}</b><small>${c.serviceIntro}</small></span></button>`).join('')}</section></main><footer>${c.name} · 校园新闻与信息服务　<span>建议使用站内搜索查找历史内容</span></footer></section>`;}
  function candidateArticle(name){const record=candidateRecords[name];return {id:`candidate-${name}`,category:record.category,title:record.title,summary:record.text,body:`${record.text} 该条目由${candidateCampus[name]===state.campusKey?'本校相关单位':'校际信息交换平台'}按日常事务归档，具体办理方式以所属单位通知为准。`};}
  function homeArticles(){const c=campus(),key=state.campusKey;const notice=c.notices.map((title,i)=>({id:`${key}-notice-${i}`,category:`校园通知 · 2026-09-${18-i*2}`,title,summary:`${c.name}已发布该项日常安排，涉及的具体时间、办理对象和入口以本通知为准。`,body:`${c.name}发布“${title}”。相关服务按照本学期工作安排分批开放，师生可通过${c.services[i%c.services.length]}栏目查询个人状态。${c.leadText} 如有流程问题，请在开放时间内向所属单位咨询。`}));const digest=c.schools.map((title,i)=>({id:`${key}-digest-${i}`,category:`院系动态 · 2026-09-${15-i*2}`,title,summary:`${title}，活动面向校内师生开放，具体报名与现场安排由承办单位发布。`,body:`${c.name}${title}。本次活动围绕秋季教学、学生项目和校园服务展开，参与者可按通知查看时间、地点和准备事项。${c.serviceIntro} 承办单位提醒，公开新闻仅用于活动介绍，不替代个人业务通知。`}));return [...notice,...digest];}
  function articleList(){return campusArticleData[state.campusKey]||[];}
  function findCampusArticle(id){return articleList().find(item=>item.id===id)||homeArticles().find(item=>item.id===id)||Object.keys(candidateCampus).map(candidateArticle).find(item=>item.id===id);}
  function articleResult(item){return `<article><time>${escape(item.category)}</time><h2>${escape(item.title)}</h2><p>${escape(item.summary)}</p><button class="text" data-action="campus-article" data-article="${escape(item.id)}">查看详情</button></article>`;}
  function genericResults(c,q){const normalized=q.replaceAll('林致远','林知远');const exactCandidate=Object.keys(candidateCampus).find(name=>candidateCampus[name]===state.campusKey&&normalized.includes(name));const general=articleList().filter(item=>item.access!=='internal').slice(0,3);const items=exactCandidate?[candidateArticle(exactCandidate),...general]:general;return items.length?items:[{id:`${state.campusKey}-notice`,category:'校园信息 · 2026-09-18',title:q?`关于“${q}”的相关校园信息`:'2026 年秋季学期校园信息汇总',summary:'相关信息已按院系工作流程归档，具体事项请以所属单位通知为准。',body:'该条目由学校信息服务平台生成，包含公开通知、办事指南和院系动态的索引。'}];}
  function campusSearch(){const c=campus(),q=(state.campusQuery||'').trim(),normalized=q.replaceAll('林致远','林知远');const results=genericResults(c,q);const relevant=c===campuses.ningchuan&&/林知远|巡检|多传感器|3.?18|事故|自动调度|设施控制/.test(normalized);if(relevant){for(const item of articleList().filter(item=>item.access==='internal'))if(!results.some(result=>result.id===item.id))results.push(item);}return `<section class="campus-page" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}">${campusHeader(true)}<nav class="campus-nav"><button class="text" data-action="route" data-route="campusHome">首页</button><span>站内搜索</span></nav><main class="campus-search-results"><p class="small muted">${q?`找到与“${escape(q)}”相关的 ${results.length} 条结果`:'请输入关键词搜索校园公开信息'}</p>${results.map(articleResult).join('')}</main></section>`;}
  function campusService(){const c=campus(),index=Math.max(0,Math.min(c.services.length-1,Number(state.campusServiceKey)||0)),name=c.services[index];const ncut=c===campuses.ningchuan&&index===1;return `<section class="campus-page" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}">${campusHeader(true)}<nav class="campus-nav"><button class="text" data-action="route" data-route="campusHome">首页</button><span>办事服务</span><span>${escape(name)}</span></nav><main class="campus-service-detail"><p class="campus-kicker">${c.name} · 服务大厅</p><h1>${escape(name)}</h1><p class="service-intro">${escape(c.serviceIntro)}</p><div class="service-detail-body"><h2>服务说明</h2><p>${ncut?'科研资料库是馆际共享材料的便民查询入口，不是高安全等级后台。公开目录可检索，历史正文使用简易校内服务码减少批量抓取。':'本服务提供线上申请、办事指南和历史记录查询。具体开放时间以当日公告和服务大厅页面为准。'}</p>${ncut?`<div class="service-clue"><b>校内共享材料服务码</b><p>格式：<strong>NC-YYYYMMDD-NNNN</strong>。日期取“首次正式发布日”；末四位由<strong>两位卷号 + 两位条目号</strong>组成。连接符、大小写不影响验证。</p><table class="data-table service-code-table"><thead><tr><th>目录候选</th><th>日期</th><th>卷 / 条</th><th>状态</th></tr></thead><tbody><tr><td>巡检平台阶段测试</td><td>2022-11-18</td><td>03 / 18</td><td>正式记录</td></tr><tr><td>巡检平台补充图集</td><td>2022-11-21</td><td>03 / 19</td><td>补充件</td></tr><tr><td>“3·18”事故处理说明</td><td>2024-03-22</td><td>06 / 24</td><td>正式附件</td></tr><tr><td>事故处置工作稿</td><td>2024-03-20</td><td>06 / 23</td><td>内部草稿</td></tr></tbody></table><p class="small muted">请选择与目标页面标题一致的“正式记录 / 正式附件”，不要使用草稿或补充件。</p></div>`:'<ul><li>网上提交：全天开放</li><li>线下窗口：工作日 08:30–17:00</li><li>咨询电话：校内服务平台转接</li></ul>'}</div><div class="form-actions"><button class="secondary" data-action="route" data-route="campusHome">返回学校首页</button><button class="primary" data-action="route" data-route="campusSearch">进入站内搜索</button></div></main><footer>${c.name} · 校园新闻与信息服务</footer></section>`;}
  function campusArticle(){const c=campus(),item=findCampusArticle(state.campusArticleId)||articleList()[0];if(!item)return campusSearch();const accessKey=item.id==='nc-project'?'campusAccessProject':item.id==='nc-memorial'?'campusAccessMemorial':'';if(item.access==='internal'&&accessKey&&!state[accessKey]){return `<section class="campus-page" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}">${campusHeader(true)}<main class="campus-access-panel"><p class="campus-kicker">校内资料库访问</p><h1>${escape(item.title)}</h1><p>该资料属于历史科研资料库，仅限校园网或校内服务码访问。公开目录保留标题和摘要，全文需要验证。</p><form data-campus-access><label for="campus-pass">校内服务码</label><input id="campus-pass" data-campus-pass autocomplete="off" placeholder="NC-YYYYMMDD-NNNN"><button class="primary">验证并查看全文</button></form><p class="small muted">全部解码线索均在学校“办事服务 / 科研资料库”中。</p><div class="form-actions"><button class="secondary" data-action="route" data-route="campusSearch">返回搜索结果</button><button class="text" data-action="campus-service" data-service="1">查看相关服务说明</button></div></main></section>`;}if(item.id==='nc-project'){state.projectRead=true;state.ncutProjectViewed=true;if(!state.incidentMailSent){state.incidentMailSent=true;deliverMail('incidentArchive');}}if(item.id==='nc-memorial'){state.memorialRead=true;state.ncutMemorialViewed=true;}if(state.ncutProjectViewed&&state.ncutMemorialViewed&&!state.sourceNoticeSent){state.sourceNoticeSent=true;deliverMail('source');}save();const related=['nc-project','nc-memorial'].includes(item.id)?`<section class="related-material"><b>归档附件</b><p>${item.id==='nc-project'?'项目报道正式留存页，含学校与负责人字段。':'事故处理说明正式附件，含5名遇难人员与调查时间线。'}</p><button class="primary" data-action="open-reference" data-file="${item.id==='nc-project'?'ningchuan-project':'ningchuan-memorial'}">打开正式附件</button><button class="text" data-action="route" data-route="oldArchive">查看衡川旧站归档</button></section>`:'';return `<section class="campus-page" style="--campus-accent:${c.accent};--campus-dark:${c.accentDark}"><main class="campus-article-page"><p class="campus-kicker">${escape(item.category)}</p><h1>${escape(item.title)}</h1><div class="campus-article-meta">${c.name} · 信息公开　|　首次正式发布日期：${escape(item.category.split('·').pop().trim())}</div><p class="campus-article-lead">${escape(item.summary)}</p>${item.body.split('。').filter(Boolean).map(p=>`<p>${escape(p)}。</p>`).join('')}${related}<div class="form-actions"><button class="secondary" data-action="route" data-route="campusSearch">返回搜索结果</button>${item.access?'<span class="small muted">本篇资料的校内服务码已验证。</span>':''}</div></main><footer>${c.name} · 校园新闻与信息服务</footer></section>`;}
  function ningchuanHome(){state.campusKey='ningchuan';return campusHome();}
  function ningchuanSearch(){state.campusKey='ningchuan';state.campusQuery=state.ncutQuery;return campusSearch();}
  function profile(){const name=state.rosterCorrected?'陆明':'林知远';return shell(`<div class="system-inner">${crumb('候补资料摘要')}<h2 class="page-title">候补资料摘要</h2><p class="small muted">本页仅显示方向接收进度中的公开字段，不提供历史附件。</p><div class="profile-sheet"><dl><dt>姓名</dt><dd>${name}</dd><dt>本科院校 / 院系</dt><dd>宁川理工大学 / 自动化学院</dd><dt>项目经历</dt><dd>轮式巡检平台多传感器定位</dd><dt>项目职责</dt><dd>负责人</dd><dt>交流讨论</dt><dd><button class="table-link" data-action="route" data-route="lzyThread">查看林知远的讨论串</button></dd></dl><div class="profile-note"><b>资料说明</b><p>公开字段来自本轮进度展示。若内容与本人材料不一致，应以正式审核通知和可核验资料为准。</p></div></div><div class="form-actions"><button class="secondary" data-action="route" data-route="rank">返回方向接收进度</button></div></div>`);}
  function newsProject(){state.campusKey='ningchuan';state.campusArticleId='nc-project';return campusArticle();}
  function newsMemorial(){state.campusKey='ningchuan';state.campusArticleId='nc-memorial';return campusArticle();}
  function lzyThread(){return `<section class="thread-page"><header><div class="thread-avatar">林</div><div><h1>林知远</h1><p>申请人交流区会话</p></div></header><div class="thread-messages"><div class="bubble mine">项目说明里，小组项目应该怎么写本人分工？</div>${state.lzyPrompted?`<div class="bubble other"><p>我写了数据整理和模型验证。别把组里别人做的也都写成自己完成的，后面问起来会很麻烦。</p><small>2026-09-22 09:35</small></div>`:''}${state.lzyBatchAsked?'<div class="bubble mine">你也参加过七月夏令营吗？</div><div class="bubble other">参加过，不过接收安排一直没定。你先按自己收到的通知走吧。</div>':''}</div><div class="thread-actions">${!state.lzyPrompted?'<button class="secondary" data-action="lzy-prompt">发送：询问项目说明</button>':''}${state.lzyPrompted&&!state.lzyBatchAsked?'<button class="secondary" data-action="lzy-batch">发送：询问夏令营</button>':''}<p class="small muted">此会话仅显示你主动发送的内容。</p></div></section>`;}
  function identityCheck(){const projectSeen=state.ncutProjectViewed||state.projectRead;const memorialSeen=state.ncutMemorialViewed||state.memorialRead;const ready=projectSeen&&memorialSeen;if(!state.campusAccessProject&&!state.campusAccessMemorial)return shell(`<div class="system-inner">${crumb('资料来源核对')}<h2 class="page-title">资料来源核对</h2><div class="info-note">历史项目资料尚未开放。本页不会展示或下载附件；请先自行搜索宁川理工大学网站，在“科研资料库”完成服务码验证。</div><div class="form-actions"><button class="secondary" data-action="route" data-route="rank">返回方向接收进度</button></div></div>`);return shell(`<div class="system-inner">${crumb('资料来源核对')}<h2 class="page-title">资料来源核对</h2><p class="small muted">仅就公开目录和已验证的历史资料提出问题；不要求提交他人的私人材料。</p>${state.identityReported?`<div class="inline-success"><b>已收到资料来源核对反馈。</b><br>本次提交对象为方向接收进度中的公开字段。候补状态未即时变化。</div><div class="task-card"><h3>处理通知</h3><p>若仍对资料来源存疑，可继续保留本人副本并等待后续安排。</p><button class="primary" data-action="route" data-route="rank">查看方向接收进度</button></div>`:`<div class="task-card"><h3>核对进度</h3><div class="source-check ${projectSeen?'checked':''}">宁川理工大学项目报道：${projectSeen?'已查看':'待查看'}</div><div class="source-check ${memorialSeen?'checked':''}">宁川理工大学学院公告：${memorialSeen?'已查看':'待查看'}</div><label class="form-choice">当前可确认的情况<select data-identity-conclusion><option value="">请选择</option><option value="same">当前展示资料与已故者的院校、项目经历及职责对应，需要说明资料来源。</option><option value="name">仅凭同名，已经确认是同一个人。</option><option value="operator">已经查明关联账号由谁操作。</option></select></label><div class="form-actions"><button class="secondary" data-action="route" data-route="rank">返回方向接收进度</button><button class="primary" data-action="submit-identity" ${ready?'':'disabled'}>提交资料来源疑问</button></div>${!ready?'<p class="small muted">请在服务码验证后，从站内搜索结果查看两条历史资料；姓名本身不足以确认身份。</p>':''}</div>`}</div>`);}
  function identityCheckV3(){return identityCheck().replaceAll('宁川理工大学学院公告','宁川理工大学事故处理说明').replaceAll('当前展示资料与已故者的院校、项目经历及职责对应','当前展示资料与事故附件中林知远的院校、项目经历及职责对应');}
  function login(){return shell(`<section class="login-hero"><div class="campus-art" aria-hidden="true"></div><div class="login-card"><h1>欢迎报考衡川大学</h1><label class="hidden" for="login-project">招生项目</label><select id="login-project"><option>推免生预报名</option><option>硕士研究生招生</option><option>博士研究生招生</option></select><div class="login-help"><b>用户名：报名号；密码：注册时填写的密码。</b><br>请通过推免生预报名系统申请，并如实核对信息。当前电脑已保留本人申请会话。</div><input aria-label="用户名" value="HC2026-0922-071" readonly><input aria-label="密码" type="password" value="retained-session" readonly><button class="primary" data-action="restore-session">恢复当前申请会话</button><div class="login-links"><span>已识别本人邮件链接</span><span>本地会话</span></div></div></section><div class="dashboard"><h2>通知公告</h2><p class="small muted">2027 年研究生招生补充材料确认工作已开始。</p></div>`,true);}
  function dayThreeReview(){return shell(`<div class="system-inner review-page">${crumb('接收安排核对')}<div class="assessment-heading"><div><p class="campus-kicker">2027级推免接收工作 · 本人申请核对</p><h2 class="page-title">接收安排核对</h2><p>请核对本轮已提交的申请与补充考核状态。接收意向由招生办公室根据本申请的审核记录生成。</p></div><span class="assessment-status">${state.dayThreeReviewSubmitted?'已提交':'待确认'}</span></div><section class="task-card"><h3>本人申请记录</h3><table class="data-table"><tbody><tr><th>申请人 / 申请号</th><td>陈言 / HC2026-0922-071</td></tr><tr><th>申请方向</th><td>0811 / H03 · 复杂系统与人机交互</td></tr><tr><th>材料提交回执</th><td>RC-0922-071 · 已接收</td></tr><tr><th>补充考核</th><td>本轮考核记录已登记，待接收安排核对</td></tr></tbody></table>${state.dayThreeReviewPending?'<div class="loading-line"><i></i><span>招生办公室正在核对本人申请与考核状态…</span></div>':state.dayThreeReviewSubmitted?'<div class="inline-success">本人接收安排核对已提交。请留意登记邮箱中的接收意向通知。</div>':'<div class="form-actions"><button class="primary" data-action="submit-day-three-review">确认本人申请记录，提交接收核对</button></div>'}<p class="small muted">本页只核对本轮招生记录，不读取本地文件夹、随手记或私人通讯。</p></section></div>`);}
  function offerStatus(){if(state.offerChoice==='reject')return '已撤回';return state.offerChoice==='continue'?'已确认':state.offerChoice==='hold'?'暂缓确认':'待本人确认';}
