  function archiveChainErrors(draft,opened){const expected={batch:'E01-HC014',subject:SUBJECT_CODE,project:'LH-17-03',report:'OBS-231211-014',receipt:'ACK-231211-083',directive:'DIR-231212-026',execution:'LOC-231212-014',unit:'H03-4',phase:'R-17 / 2027-A1'};const errors=[];if(!archiveRecords.every(r=>opened[r.id]))errors.push('仍有引用原件未查看，暂不能确认流转顺序。');if(!Object.keys(expected).every(key=>chatNormalize(draft[key])===chatNormalize(expected[key])||(key==='unit'&&chatNormalize(draft[key])===chatNormalize('H03-4 · 系统反馈与对照'))))errors.push('填写的编号或预排字段未能相互对应。请核对原件的来件、答复及依据来文。');return errors;}
  function flowReview(){return `<div class="flow-local-page"><header><small>陈言 / 本地笔记</small><h1>流转顺序与预排字段核对</h1><p>分别记录原件之间的引用和本人当前预排。这里不会把历史执行写成本人已经入学。</p></header><form data-flow-review><div class="flow-field-grid">${flowFields.map(([key,label])=>`<label>${label}<input name="${key}" aria-label="${label}" value="${escape(state.archiveChainDraft[key]||'')}" ${state.archiveChainComplete?'readonly':''} autocomplete="off"></label>`).join('')}</div>${state.archiveChainComplete?'<div class="inline-success">核对记录已保存。原始留存不变，范既白的回复保留在会话中。</div>':state.archiveError?`<p class="archive-error" role="alert">${escape(state.archiveError)}</p>`:''}<div class="form-actions">${!state.archiveChainComplete?'<button class="primary">保存并请范既白核对</button>':''}<button type="button" class="secondary" data-action="route" data-route="liaisonArchive">返回归档检索</button>${state.archiveChainComplete?'<button type="button" class="secondary" data-action="open-fan-day3">查看范既白会话</button>':''}</div><p class="small muted">发送内容仅含上述编号与字段。你的随手记、其他候补者材料不会一并发送。</p></form>${state.archiveChainComplete?'<section class="flow-boundary"><h2>还有一项没有核实</h2><p>历史回复与执行已经对上。当前预排沿用同名阶段，但旧指令是否仍约束本届接收、谁将申请号写入当前批次，仍缺少当期文件。</p><p>接收意向确认也不等于同意入学后的研究使用。</p></section>':''}</div>`;}
