  function fieldCheck(){return shell(`<div class="system-inner field-check-page">${crumb('本人申请字段核对')}<h2 class="page-title">本人申请字段核对</h2><p>本申请关联了接收预排。如需核对字段来源，可向招生事务窗口提交下列本人信息。</p><section class="task-card"><dl class="offer-fields"><div><dt>申请人 / 申请号</dt><dd>陈言 / HC2026-0922-071</dd></div><div><dt>拟接收文书</dt><dd>INT-0924-071</dd></div><div><dt>查询事项</dt><dd>C型分类、H03-4培养单元与R-17 / 2027-A1阶段的登记依据。</dd></div></dl>${state.fieldRequestPending?'<div class="loading-line"><i></i><span>字段核对请求已送达，正在等待经办回复…</span></div>':state.fieldReplyReceived?'<div class="inline-success">唐敏的核对回复已送达登记邮箱。本人的回执副本已留存。</div><div class="form-actions"><button class="secondary" data-action="open-current-receipt">查看字段核对回执</button><button class="secondary" data-action="route" data-route="currentService">进入应用服务平台</button></div>':'<button class="primary" data-action="request-field-check">核对发送内容</button>'}<p class="small muted">只发送以上本申请字段。不附加本地档案、聊天、备忘录或其他申请人的资料。</p></section><button class="secondary" data-action="route" data-route="allocation">返回接收安排说明</button></div>`);}
