  function browserPage(){const route=currentRoute();const pages={closureDirectory,closureHome,closureReport,closureStatus,closureArchive,closureDecision,closureFinalChat,home,form:formPage,dashboard,departments,notice,status,result,rank,candidateSummary,questionnaire,assessment,sourceDesk,interviewCompare,oldArchive:oldArchiveV3,followup,forum,profile,dayThreeReview,offer,allocation,fieldCheck,currentService,currentLookup,currentProof,liaisonHome,liaisonArticle,liaisonArchive,flowReview,ningchuanHome,ningchuanSearch,campusHome,campusSearch,campusArticle,campusService,newsProject,newsMemorial,lzyThread,identityCheck:identityCheckV3,login,blank:()=>'<div class="blank-page">在地址栏输入已获得的网址</div>'};return `<div class="route-frame" data-route="${route}">${route.startsWith('closureArticle:')?closureArticle(route.split(':')[1]):route.startsWith('closureUnit:')?closureUnit(route.split(':')[1]):route.startsWith('currentArticle:')?currentArticle(route.split(':')[1]):route.startsWith('prototypeNotice:')?prototypeNotice(route.split(':')[1]):route.startsWith('liaisonArticle:')?liaisonArticle(route.split(':')[1]):(pages[route]||pages.blank)()}</div>`;}
  function browser(){const tab=currentTab();return `<div class="window-tabs">${state.tabs.map((t,i)=>`<div class="browser-tab ${i===state.activeTab?'selected':''}"><button class="text tab-label" data-action="select-tab" data-tab="${i}" style="color:inherit">${escape(routeLabel(t.history[t.index]))}</button>${state.tabs.length>1?`<button class="close-tab" data-action="close-tab" data-tab="${i}" aria-label="关闭标签">×</button>`:''}</div>`).join('')}<button class="new-tab" data-action="new-tab" aria-label="新标签页">＋</button></div><div class="browser-toolbar"><button class="nav-icon" data-action="back" aria-label="后退" ${tab.index===0?'disabled':''}>‹</button><button class="nav-icon" data-action="forward" aria-label="前进" ${tab.index===tab.history.length-1?'disabled':''}>›</button><button class="nav-icon" data-action="refresh" aria-label="刷新">⟳</button><form class="address-box" id="address-form"><span aria-hidden="true">▤</span><input aria-label="浏览器地址栏" id="address" value="${escape(routePath(currentRoute()))}" autocomplete="off" spellcheck="false"></form><button class="nav-icon" data-action="history" aria-label="历史记录" title="历史记录">◷</button></div><div class="browser-content" data-scroll-key="browser:${tab.id}:${currentRoute()}">${browserPage()}</div>`;}
  function downloads(){return state.savedFiles.map(item=>({...item,...(window.DIBU_DOCUMENTS[item.id]||{}),name:item.name.replace(/\.txt$/i,'.pdf'),size:window.DIBU_DOCUMENTS[item.id]?.size||item.size||'留存副本'}));}
