  function submitRosterComplaint(){
    const r=state.rosterInquiry;
    if(state.day<2||!(r.discussed||r.submitted||state.dayThreeOfferReleased)||rosterReviewPending())return false;
    r.validationShown=true;
    if(Object.keys(rosterRequiredErrors(r.draft)).length){save();updateRosterFormValidation($('[data-roster-complaint]'));return false;}
    if(!Array.isArray(r.attempts))r.attempts=[];
    const id=Math.max(0,...r.attempts.map(a=>a.id))+1;
    const attempt={id,day:state.day>=3?3:2,status:'pending',fileId:'roster-complaint-attempt-'+id,submission:Object.fromEntries(Object.keys(rosterFormFields).map(key=>[key,String(r.draft[key]||'')]))};
    r.attempts.push(attempt);r.validationShown=false;delete r.sourceSnapshot;
    state.dayTwoReadyNotified=false;
    state.notificationQueue=state.notificationQueue.filter(n=>!(n.type==='memo'&&n.id==='day-two-ready'));
    saveRosterAttemptReceipt(attempt);registerRosterAttemptMail(attempt);deliverMail('rosterReceipt-'+id);
    closeDialog();save();render();toast('本次申报已登记，请在邮箱查收核查回复。');
    setTimeout(()=>finishRosterReview(id),1400);return true;
  }
  function finishRosterReview(id){
    const r=state.rosterInquiry,attempt=(r.attempts||[]).find(a=>a.id===id);
    if(!attempt||attempt.status!=='pending')return;
    if(Object.keys(rosterComplaintErrors(attempt.submission)).length===0){
      attempt.status='accepted';attempt.followup=r.result||state.dayThreeOfferReleased?'resolved':r.submitted?'registered':'next-day';
      if(!r.submitted){r.submitted=true;r.submission=structuredClone(attempt.submission);r.successfulAttemptId=id;}
      state.dayTwoChecklist.appeal=true;
    }else attempt.status='no-change';
    registerRosterAttemptMail(attempt);deliverMail('rosterResult-'+id);state.memoUnread=true;save();render();
    updateRosterFormValidation($('[data-roster-complaint]'));
  }
  function releaseRosterResult(){
    if(!state.rosterInquiry.submitted)return false;
    state.rosterInquiry.result=true;state.dayThreeReviewSubmitted=true;state.dayThreeReviewPending=false;state.dayThreeOfferReleased=true;state.dayThreeChecklist.review=true;
    deliverMail('offer');state.selectedMail='offer';return true;
  }
