      conversation=`<section class="chat-conversation"><header>范既白 <small>旧站维护 · 仅你们可见</small></header><div class="thread-messages" data-scroll-key="chat:fan">${messages.length?messages.map(m=>`<div class="bubble ${m.side}">${escape(m.text)}</div>`).join(''):'<div class="chat-quiet">你已添加范既白。他还没有发来消息。</div>'}${state.fanTyping?'<div class="typing-indicator"><i></i><i></i><i></i><span>范既白正在输入…</span></div>':''}${packetCount?`<div class="chat-file-note"><b>已收到 ${packetCount} 份资料</b><span>原件保存在“文件 / 下载与留存”。</span><button class="text" data-action="files-folder" data-folder="downloads">打开文件夹</button></div>`:''}</div>${state.currentFollowupDelivered?`<div class="chat-followups"><span>当期关联之后</span><button class="secondary" data-action="closure-annex" ${state.closure.annexPending?'disabled':''}>${state.closure.annexReceived?'打开交接续卷':'核对事故前交接目录'}</button><button class="secondary" data-action="route" data-route="closureDirectory">公开办事与联系目录</button></div>`:''}${state.fanModelIndexReceived?`<div class="chat-file-open"><button class="secondary" data-action="open-file" data-file="fan-model-handoff">${state.fanModelIndexOpened?'重新打开模型交接索引':'打开刚收到的模型交接索引'}</button></div>`:''}${state.day>=3&&state.archiveChainComplete?`<div class="chat-followups"><span>本人当期字段的来源</span><button class="secondary" data-action="route" data-route="fieldCheck">${state.fieldReplyReceived?'查看本人字段核对回复':'向招生窗口核对本人字段'}</button></div>`:''}${state.day>=3&&state.allocationOpened&&state.fanResponsibilityChecked?`<div class="chat-followups"><span>昨日提到的上报批次</span><button class="secondary" data-action="ask-archive-transfer" ${state.archiveTransferPending?'disabled':''}>${state.archiveTransferPending?'正在等待回复…':state.archiveTransferReceived?'打开转交留存入口':'询问 E01-HC014 的留存去向'}</button></div>`:''}${state.fanModelIndexOpened&&!state.fanResponsibilityChecked?'<div class="chat-followups"><span>模型索引之外，还能核对范既白经手的责任范围</span><button class="secondary" data-action="fan-responsibility">追问整理与异常上报</button></div>':''}${rosterInquiryActions()}<form class="chat-composer" data-fan-chat><textarea data-fan-message aria-label="发送给范既白的消息" placeholder="输入消息，按 Enter 发送；Shift+Enter 换行" ${state.fanTyping?'disabled':''}></textarea><button class="primary" ${state.fanTyping?'disabled':''}>发送</button></form></section>`;
