  const chatNormalize=value=>String(value||'').normalize('NFKC').toUpperCase()
    .replaceAll('林致远','林知远').replaceAll('范即白','范既白').replaceAll('范继白','范既白')
    .replace(/[\s\p{P}\p{S}_]+/gu,'');
  const hasChatKeyword=(value,keywords)=>{const normalized=chatNormalize(value);return keywords.some(keyword=>normalized.includes(chatNormalize(keyword)));};
  const isNegated=value=>/(不想|不要|不用|无需|别查|别发|没必要|不是在问|并非询问)/.test(value);
  const chatKeywordNodes={
    archiveInitial:{stage:0,source:'旧站归档说明、旧附件与宁川资料',groups:{
      name:['林知远','林致远'],
      attachment:['旧附件','项目经历填写示例',MATERIAL_CODE,'HC23-XLY-B17-042'],
      archive:['归档','旧站','迁移','缺失']
    }},
    archiveLink:{stage:1,source:'维护员首轮回复',keywords:['材料整理任务号','主体索引','当前显示编号','当前页面展示编号',MATERIAL_CODE,SUBJECT_CODE,'HC-014','HC23-XLY-B17-042','JI-22-014']},
    fanInitial:{stage:0,source:'旧站维护回复及可见归档',keywords:['林知远','林致远','旧附件','项目经历填写示例','材料整理任务号','主体索引',MATERIAL_CODE,SUBJECT_CODE,'HC23-XLY-B17-042','JI-22-014','HC-014']},
    fanPacket:{stage:1,source:'范既白首轮回复',keywords:['编号对照','字段说明']},
    fanCodes:{stage:2,source:'编号对照与字段说明',keywords:['材料整理任务号','主体索引','教学案例索引','当前页面展示编号','当前显示编号',MATERIAL_CODE,SUBJECT_CODE,'HC-014','HC23-XLY-B17-042','JI-22-014']},
    fanCompareOpen:{stage:3,source:'访谈附件名称与说明',keywords:['原始转写','原始记录','转写','整理摘要','摘要']},
    fanCompareFinish:{stage:3,source:'原始转写与整理摘要',keywords:['停止','暂停','拒绝','不同意','已知悉','愿意继续']},
    fanModel:{stage:4,source:'模型交接索引',keywords:['模型交接索引','模型','时间核对','前台展示','事故','主体链','MX-24-014']}
  };
  function delayedFanReplies(target,replies,after){
    state[target==='archive'?'fanArchiveTyping':'fanTyping']=true;save();render();
    setTimeout(()=>{const list=target==='archive'?state.fanArchiveMessages:state.fanMessages;replies.forEach(text=>list.push({side:'other',text}));if(after)after();state[target==='archive'?'fanArchiveTyping':'fanTyping']=false;save();render();},850);
  }
  function handleFanArchiveMessage(message){
    state.fanArchiveMessages.push({side:'mine',text:message});
    if(isNegated(message)){save();render();return;}
    const initial=chatKeywordNodes.archiveInitial.groups;
    if(state.fanArchiveStage===0&&Object.values(initial).some(keywords=>hasChatKeyword(message,keywords))){
      const opener=hasChatKeyword(message,initial.name)?'你是在核对林知远那条旧记录？我原以为迁移后的缺口不会再有人追。':hasChatKeyword(message,initial.attachment)?'你提到的旧附件，是迁移前留下的项目经历填写示例。它的编号不能直接当成学生编号。':'归档迁移确实留下了缺口。公开站只搬了公示和活动附件，旧目录里的编号层级没有一起解释。';
      delayedFanReplies('archive',[opener,`先记住两个字段：${MATERIAL_CODE} 是材料整理任务号，${SUBJECT_CODE} 是主体索引；页面上的当前显示编号不能替代它们。`],()=>{state.fanArchiveStage=1;state.fanArchiveContext='lzy-codes';});return;
    }
    if(state.fanArchiveStage===1&&hasChatKeyword(message,chatKeywordNodes.archiveLink.keywords)){
      delayedFanReplies('archive',['对，你问到的是迁移时最容易混在一起的地方。当前显示号只服务前台，不能替代主体索引。','我手里还有两页经手留存。公开窗口不方便传，给你一个即时通讯账号：范既白。先只核对文件，不要转发。'],()=>{state.fanArchiveStage=2;state.fanContactOffered=true;});return;
    }
    if(state.fanArchiveStage>=2&&(Object.values(initial).some(keywords=>hasChatKeyword(message,keywords))||hasChatKeyword(message,chatKeywordNodes.archiveLink.keywords)))delayedFanReplies('archive',['这部分已经核对过了。我能确认的只有自己经手的目录和编号用途；更深的记录到即时通讯里按文件逐页核对。']);
    else{save();render();}
  }
  function handleFanMessage(message){
    state.fanMessages.push({side:'mine',text:message});
    if(isNegated(message)){save();render();return;}
    if(state.day===2&&state.fanModelIndexOpened&&hasChatKeyword(message,['投诉','名单有问题','名单核查','往前','递补','候补第一'])&&!state.rosterInquiry.discussed){askRosterInquiry(false);return;}
    if(state.day>=3&&state.allocationOpened&&state.fanResponsibilityChecked&&hasChatKeyword(message,['E01-HC014','上报','留存去向','转交登记','下行回复'])){if(state.archiveTransferReceived)delayedFanReplies('chat',['转交登记 LH-2024-HC-014-0817 与 https://service.liheng.example/archive 都已发给你。只查此次转交范围，别把它当成整个项目后台。']);else{state.archiveTransferPending=true;state.fanTyping=true;save();render();setTimeout(finishArchiveTransfer,1150);}return;}
    if(state.day>=3&&state.archiveChainComplete&&hasChatKeyword(message,['当期','2027-A1','当前','分配依据','接收','R-17'])){delayedFanReplies('chat',[state.fieldReplyReceived?'你取得的当期回复要连同出处保存。我只能核对旧经手记录，不能替你确认本届所有后台。':'我没有当期分配依据。你可以向招生窗口只提交本人申请号与预排字段，要求说明来源；不需要把私下取得的旧档一起交出去。']);return;}
    if(state.day>=3&&state.archiveTransferReceived&&hasChatKeyword(message,['校验','登录','密码'])){delayedFanReplies('chat',['不要拿自己的申请号试。转交登记已经在留存文件里，平台档案服务说明会解释哪些字段需要保留。']);return;}
    const stage=Number(state.fanQuestionStage)||0;
    if(stage===0&&hasChatKeyword(message,chatKeywordNodes.fanInitial.keywords)){
      delayedFanReplies('chat',['你也在查林知远这条记录？我还以为旧站上那几处编号不会再有人注意。',`先说清楚：${MATERIAL_CODE} 是材料整理任务号，${SUBJECT_CODE} 是主体索引。我经手过编号对照和字段说明。`],()=>{state.fanQuestionStage=1;state.fanContext='lzy-codes';});return;
    }
    if(stage===1&&hasChatKeyword(message,chatKeywordNodes.fanPacket.keywords)){
      delayedFanReplies('chat',['有两页是我当助管时经手的：编号对照和字段说明。先在你自己的电脑里看，别转出去。','我发过去了。你可以直接拿材料整理任务号、主体索引或当前显示编号来问。'],()=>{receiveFanPacket();state.fanQuestionStage=2;});return;
    }
    if(stage===2&&state.fanFirstPacketReceived&&hasChatKeyword(message,chatKeywordNodes.fanCodes.keywords)){
      state.fanCodesVerified=true;
      delayedFanReplies('chat',['对上了。材料任务、主体索引和当前显示号分属不同层级，不能互相替代。','我再发四页：培养分组、同一次访谈的原始转写与整理摘要，还有任务规则。R-17 是正式入学后的阶段。先核对原始转写和整理摘要。'],()=>{receiveFanSecondPacket();state.fanQuestionStage=3;state.fanComparisonPrompted=false;});return;
    }
    if(stage===3){
      if(!state.fanComparisonPrompted&&hasChatKeyword(message,chatKeywordNodes.fanCompareOpen.keywords)){
        delayedFanReplies('chat',['这两页记的是同一次访谈。请按上下文核对两份原件，在对照页保留你的批注，我再核对当时经手的流转记录。'],()=>{state.fanComparisonPrompted=true;});return;
      }
      if(state.fanComparisonPrompted&&hasChatKeyword(message,chatKeywordNodes.fanCompareFinish.keywords)){
        delayedFanReplies('chat',['先把两份 PDF 并排读完，并在记录对照页里手动标记你认为改变原意的段落。','聊天里的判断不会替代原始文件对照；标记齐全后点击“保存观察”，我再继续说明编号和时间。']);
        return;
      }
    }
    if(stage>=4&&hasChatKeyword(message,chatKeywordNodes.fanModel.keywords)){delayedFanReplies('chat',['现有页只能确认：事故在前，模型在2024年8月完成，前台展示在2026年。批准链和其他账号，我手里的材料证明不了。']);return;}
    save();render();
  }
  function classifySurvey(values){
    const a=values.map(Number);
    const D=a[0]+(6-a[1])+a[2]+(6-a[3]);
    const E=a[4]+(6-a[5])+a[6]+(6-a[7]);
    return D>=16&&E>=16&&a[8]>=4&&a[9]>=4?'C':D>=16?'A':'B';
  }
