    'end-day-one'(){if(!canEndDayOne()){const missing=[];if(!state.submitted)missing.push('提交申请');if(!state.rankViewed)missing.push('查看候补进度');if(!state.survey.result)missing.push('完成申请人问卷');if(!(state.ncutProjectViewed&&state.ncutMemorialViewed))missing.push('核对两篇宁川历史资料');if(!state.archiveUrlSaved)missing.push('保留旧站网址');if(!state.dayOneChecklist.sources)missing.push('整理本人材料来源');if(!state.dayOneChecklist.version)missing.push('核对提交版与本地草稿');if(!state.dayOneChecklist.candidates)missing.push('完成候补流程横向核对');toast(`今天还有内容未核对：${missing.join('、')}。`);return;}modal('<h2>结束9月22日的安排</h2><p class="form-text">申请、问卷、历史资料、来源分类和版本核对已经留存。继续后日期将推进到9月23日，现有笔记与保存副本不会清除。</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">再检查一下</button><button class="primary" data-action="advance-day">继续到9月23日</button></div>','','日期推进');},
