    'end-day-two'(){if(rosterReviewPending()){toast('名单核查仍在处理中，请先查看邮箱回复。');return;}if(!state.rosterInquiry.submitted){toast('请先查看名单核查回复，核对后可继续提交申报。');return;}if(!canEndDayTwo()){const missing=dayTwoItems.filter(([key])=>!state.dayTwoChecklist[key]).map(([,label])=>label);toast(`今天还有内容未核对：${missing.join('、')}。`);return;}modal('<h2>结束9月23日的安排</h2><p class="form-text">资料核对与名单核查申请已留存。招生办公室将在明日回复名单问题。继续后日期将推进到9月24日，现有笔记、文件与聊天记录不会清除。</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">再检查一下</button><button class="primary" data-action="advance-day-two">继续到9月24日</button></div>','','日期推进');},
