    'fan-archive-topic'(el){if(state.fanArchiveTyping||state.fanArchiveStage>0)return;const replies={missing:['2023年林知远的招生记录为什么缺失？',['你是在找林知远那一年的记录？我以为那块缺口没人会追。','公开站只搬了公示和活动附件，个人材料没进目录。你看到的附件号也不像学籍号。']],material:['HC23-XLY-B17-042 是公开附件编号吗？',['等等，你手里也有 HC23-XLY-B17-042？','这个号是 2023 年夏令营的一次材料整理任务。我见过那张表，它记的是处理批次，不是人。']],index:['JI-22-014 与招生归档有什么关系？',['JI-22-014？这个格式我见过，但它不属于招生材料编号。','更像教学案例的主体索引。先别把它和材料号并成一个。']]};const pair=replies[el.dataset.topic]||replies.material;state.fanArchiveMessages.push({side:'mine',text:pair[0]});state.fanArchiveTyping=true;save();render();setTimeout(()=>{pair[1].forEach(text=>state.fanArchiveMessages.push({side:'other',text}));state.fanArchiveTyping=false;state.fanArchiveStage=1;save();render();},900);},
