    'closure-open'(el){const c=state.closure;if(!c.annexReceived||!state.archiveAccess)return;const r=closureRecords.find(r=>r.id===el.dataset.file);if(!r||chatNormalize(c.archiveQuery)!==chatNormalize(r.ref))return;closureAddDocument(r.id,r.name,r.date);c.opened[r.id]=true;state.dayThreeChecklist.critical=closureRecords.every(r=>c.opened[r.id]);save();render();showFile(r.id);},
    'closure-submit'(){const c=state.closure;if(c.pending||c.decision)return;if(closureReportErrors(c.caseDraft,c).length)return;const draft=structuredClone(c.caseDraft);draft.files=draft.files.filter(id=>state.savedFiles.some(f=>f.id===id));c.caseSubmitted=draft;c.revision++;c.pending='receipt';c.status='none';c.error='';closeDialog();save();go('closureStatus');setTimeout(finishClosureReceipt,1100);},
    'closure-poll'(el){const c=state.closure;if(c.pending||!c.caseSubmitted)return;const kind=el.dataset.kind;if(kind==='review'&&c.status!=='received')return;if(kind==='measures'&&c.status!=='verified')return;if(kind==='surface'&&(!c.surfaceAvailable||c.surfaceDone))return;if(!['review','measures','surface'].includes(kind))return;c.pending=kind;save();render();setTimeout(kind==='review'?finishClosureReview:kind==='measures'?finishClosureMeasures:finishClosureSurface,1250);},
    'closure-choice'(el){const c=state.closure,choice=el.dataset.choice;if(c.decision||c.decisionPending||!['accept','reject','hold'].includes(choice))return;const protectedRoute=c.status==='measures';const copy=choice==='reject'?'拒绝并撤回本方向接收意向；停止本人预排。':choice==='hold'?'暂缓决定，并明确停止本人预排。':protectedRoute?'接受附独立核验条件的接收意向；涉事预排仍暂停，不因此入学或同意研究参与。':state.fanModelIndexOpened?'接受接收意向。你的留存尚无涉事预排暂停反馈；若随后继续正式录取、入学与原培养路线，已发现的风险仍未被阻断。':'接受接收意向。正式录取与入学仍需后续手续，不代表同意参加研究。';modal(`<h2>确认最终选择</h2><p class="form-text">${copy}</p><p class="small muted">只提交本人意向，不发送调查文件或自写笔记。</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">返回核对</button><button class="primary" data-action="closure-confirm-choice" data-choice="${choice}">确认${choice==='accept'?'接受':choice==='reject'?'撤回':'暂缓'}</button></div>`,'','本人最终意向确认');},
